# This code has been fully generated by an AI.
"""Command line interface used by the my Velo Go server.

Protocol
--------
* stdout carries JSON Lines events only, one object per line with an "event" key.
* stderr carries human-readable logs.
* Secrets (password, MFA code) are read from stdin, never from arguments,
  because arguments are visible in the process list.
* The exit code tells the caller what to do next, see ``Exit``.

Commands
--------
login   stdin line 1: {"email": ..., "password": ...}
        emits {"event": "mfa_required"} if Garmin asks for a code and then
        reads stdin line 2: {"mfa_code": ...}. Tokens are stored in --tokenstore.
status  checks whether the stored tokens are still accepted.
sync    downloads original FIT files of activities since --since into --out.
"""

from __future__ import annotations

import argparse
import datetime as dt
import io
import json
import logging
import os
import sys
import time
import zipfile
from collections.abc import Callable, Iterable
from enum import IntEnum
from pathlib import Path
from typing import Any, TextIO

log = logging.getLogger("garmin_fetch")

FIT_MAGIC = b".FIT"


class Exit(IntEnum):
    OK = 0
    ERROR = 1
    AUTH_REQUIRED = 2  # tokens missing/expired or credentials rejected → run login
    RATE_LIMITED = 3  # Garmin throttles → retry much later
    MFA_FAILED = 4


class FetchError(Exception):
    def __init__(self, exit_code: Exit, code: str, message: str) -> None:
        super().__init__(message)
        self.exit_code = exit_code
        self.code = code


# Classified by name so that the mapping does not require importing
# garminconnect (keeps tests independent from the library).
_ERRORS = {
    "GarminConnectAuthenticationError": (Exit.AUTH_REQUIRED, "auth_required"),
    "GarminConnectTooManyRequestsError": (Exit.RATE_LIMITED, "rate_limited"),
    "GarminConnectConnectionError": (Exit.ERROR, "connection"),
    "GarminConnectNotFoundError": (Exit.ERROR, "not_found"),
}


def classify(exc: BaseException) -> FetchError:
    if isinstance(exc, FetchError):
        return exc
    for cls in type(exc).__mro__:
        if cls.__name__ in _ERRORS:
            exit_code, code = _ERRORS[cls.__name__]
            return FetchError(exit_code, code, str(exc))
    return FetchError(Exit.ERROR, "internal", f"{type(exc).__name__}: {exc}")


class Events:
    def __init__(self, out: TextIO) -> None:
        self._out = out

    def emit(self, event: str, **fields: Any) -> None:
        self._out.write(json.dumps({"event": event, **fields}, ensure_ascii=False) + "\n")
        self._out.flush()


ClientFactory = Callable[..., Any]


def default_client_factory(**kwargs: Any) -> Any:
    from garminconnect import Garmin  # imported lazily: heavy and network-related

    return Garmin(**kwargs)


def _read_json_line(stdin: TextIO, what: str) -> dict[str, Any]:
    line = stdin.readline()
    if not line:
        raise FetchError(Exit.ERROR, "bad_input", f"expected {what} on stdin, got EOF")
    try:
        value = json.loads(line)
    except json.JSONDecodeError as exc:
        raise FetchError(Exit.ERROR, "bad_input", f"invalid JSON for {what}") from exc
    if not isinstance(value, dict):
        raise FetchError(Exit.ERROR, "bad_input", f"{what} must be a JSON object")
    return value


def cmd_login(args: argparse.Namespace, events: Events, stdin: TextIO, factory: ClientFactory) -> Exit:
    creds = _read_json_line(stdin, "credentials")
    email, password = creds.get("email"), creds.get("password")
    if not email or not password:
        raise FetchError(Exit.ERROR, "bad_input", "email and password are required")

    def prompt_mfa() -> str:
        events.emit("mfa_required")
        code = str(_read_json_line(stdin, "MFA code").get("mfa_code", "")).strip()
        if not code:
            raise FetchError(Exit.MFA_FAILED, "mfa_failed", "empty MFA code")
        return code

    tokenstore = _prepare_tokenstore(args.tokenstore)
    client = factory(email=email, password=password, prompt_mfa=prompt_mfa)
    # With credentials and a tokenstore path, garminconnect performs a fresh
    # login and persists the tokens (0600) itself.
    client.login(str(tokenstore))
    events.emit("login_ok")
    return Exit.OK


def _prepare_tokenstore(path: str) -> Path:
    p = Path(path)
    p.mkdir(parents=True, exist_ok=True, mode=0o700)
    return p


def _login_with_tokens(args: argparse.Namespace, factory: ClientFactory) -> Any:
    client = factory()
    client.login(str(args.tokenstore))
    return client


def cmd_status(args: argparse.Namespace, events: Events, _stdin: TextIO, factory: ClientFactory) -> Exit:
    _login_with_tokens(args, factory)
    events.emit("status", logged_in=True)
    return Exit.OK


def cmd_sync(args: argparse.Namespace, events: Events, _stdin: TextIO, factory: ClientFactory) -> Exit:
    client = _login_with_tokens(args, factory)
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    known = _read_known_ids(args.known_ids)

    activities = client.get_activities_by_date(args.since, None, None, "asc")
    downloaded = skipped = no_file = 0
    for act in activities:
        activity_id = str(act.get("activityId", ""))
        if not activity_id.isdigit():
            continue
        meta = _metadata(act)
        target = out / f"{activity_id}.fit"
        if activity_id in known or target.exists():
            skipped += 1
            events.emit("activity", status="known", **meta)
            continue

        try:
            payload = client.download_activity(activity_id, dl_fmt=type(client).ActivityDownloadFormat.ORIGINAL)
        except Exception as exc:  # noqa: BLE001 - classified below
            err = classify(exc)
            if err.code != "not_found":
                raise err from exc
            no_file += 1  # e.g. manually created activities have no file
            events.emit("activity", status="no_file", **meta)
            continue

        fit = extract_fit(payload)
        if fit is None:
            no_file += 1
            events.emit("activity", status="no_file", **meta)
            continue
        _write_atomic(target, fit)
        _write_atomic(out / f"{activity_id}.json", json.dumps(meta, ensure_ascii=False, indent=2).encode())
        downloaded += 1
        events.emit("activity", status="downloaded", file=str(target), **meta)
        if args.delay > 0:
            time.sleep(args.delay)  # be gentle with an unofficial API

    events.emit("done", listed=len(activities), downloaded=downloaded, skipped=skipped, no_file=no_file)
    return Exit.OK


def _metadata(act: dict[str, Any]) -> dict[str, Any]:
    activity_type = act.get("activityType") or {}
    return {
        "activity_id": str(act.get("activityId")),
        "name": act.get("activityName"),
        "type": activity_type.get("typeKey"),
        "start_time_gmt": act.get("startTimeGMT"),
        "distance_m": act.get("distance"),
        "duration_s": act.get("duration"),
        "device_id": act.get("deviceId"),
    }


def _read_known_ids(path: str | None) -> set[str]:
    if not path:
        return set()
    try:
        lines: Iterable[str] = Path(path).read_text().splitlines()
    except FileNotFoundError:
        return set()
    return {line.strip() for line in lines if line.strip()}


def extract_fit(payload: bytes) -> bytes | None:
    """Return the FIT file from Garmin's "original" download.

    Garmin wraps the original upload in a ZIP; a bare FIT file is accepted too.
    Non-FIT originals (e.g. GPX/TCX uploads from other apps) yield None.
    """
    if payload[8:12] == FIT_MAGIC:
        return payload
    if not zipfile.is_zipfile(io.BytesIO(payload)):
        return None
    with zipfile.ZipFile(io.BytesIO(payload)) as zf:
        for info in zf.infolist():
            if info.filename.lower().endswith(".fit"):
                data = zf.read(info)
                if data[8:12] == FIT_MAGIC:
                    return data
    return None


def _write_atomic(target: Path, data: bytes) -> None:
    tmp = target.with_name(target.name + ".part")
    with open(tmp, "wb") as fh:
        fh.write(data)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, target)


def _date(value: str) -> str:
    dt.date.fromisoformat(value)
    return value


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="garmin-fetch", description=__doc__.split("\n\n")[0])
    parser.add_argument("-v", "--verbose", action="store_true", help="debug logging on stderr")
    sub = parser.add_subparsers(dest="command", required=True)

    for name, help_text in (
        ("login", "log in with credentials from stdin and store tokens"),
        ("status", "check stored tokens"),
        ("sync", "download new activities as original FIT"),
    ):
        p = sub.add_parser(name, help=help_text)
        p.add_argument("--tokenstore", required=True, help="directory for garmin_tokens.json")
        if name == "sync":
            p.add_argument("--out", required=True, help="inbox directory for <activityId>.fit/.json")
            p.add_argument("--since", required=True, type=_date, help="first day to fetch (YYYY-MM-DD)")
            p.add_argument("--known-ids", help="file with already imported activity ids, one per line")
            p.add_argument("--delay", type=float, default=1.0, help="seconds between downloads")
    return parser


COMMANDS = {"login": cmd_login, "status": cmd_status, "sync": cmd_sync}


def main(
    argv: list[str] | None = None,
    stdin: TextIO = sys.stdin,
    stdout: TextIO = sys.stdout,
    factory: ClientFactory = default_client_factory,
) -> int:
    args = build_parser().parse_args(argv)
    logging.basicConfig(
        stream=sys.stderr,
        level=logging.DEBUG if args.verbose else logging.WARNING,
        format="%(levelname)s %(name)s: %(message)s",
    )
    events = Events(stdout)
    try:
        return int(COMMANDS[args.command](args, events, stdin, factory))
    except Exception as exc:  # noqa: BLE001 - every failure is reported as event
        err = classify(exc)
        log.debug("command failed", exc_info=True)
        events.emit("error", code=err.code, message=str(err))
        return int(err.exit_code)
